<?php
declare(strict_types=1); require __DIR__.'/../config/config.php'; require_role(['pharmacist','manager','admin']);
function h($v){return htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');}
$pdo=db();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='bulk_receive'){
 try{$items=json_decode($_POST['items']??'[]',true)?:[];if(!$items)throw new RuntimeException('Add at least one medicine.');$pdo->beginTransaction();$n=0;
 foreach($items as $x){$mid=(int)($x['medicine_id']??0);$m=$pdo->prepare('SELECT * FROM medicines WHERE id=? AND active=1 FOR UPDATE');$m->execute([$mid]);$med=$m->fetch();if(!$med)throw new RuntimeException('Medicine not found.');$boxes=max(0,(int)($x['boxes']??0));$strips=max(0,(int)($x['strips']??0));$tabs=max(0,(int)($x['tabs']??0));$qty=$boxes*(int)$med['strips_per_box']*(int)$med['units_per_strip']+$strips*(int)$med['units_per_strip']+$tabs;if($qty<1)throw new RuntimeException('Quantity is zero for '.$med['name']);$batch=trim((string)($x['batch']??''))?:null;$expiry=trim((string)($x['expiry']??''))?:null;$cost=max(0,(float)($x['cost']??0));$pdo->prepare('INSERT INTO batches(medicine_id,batch_no,expiry_date,units_received,units_remaining,purchase_unit_cost) VALUES(?,?,?,?,?,?)')->execute([$mid,$batch,$expiry,$qty,$qty,$cost]);$bid=(int)$pdo->lastInsertId();$pdo->prepare("INSERT INTO stock_movements(medicine_id,batch_id,movement_type,quantity_units,note) VALUES(?,?, 'purchase',?,?)")->execute([$mid,$bid,$qty,'Bulk inventory receive']);$n++;}
 $pdo->commit();audit_log('bulk_stock_received',$n.' medicines received');header('Location: inventory_bulk.php?saved='.$n);exit;
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}
$meds=$pdo->query('SELECT id,name,generic_name,strength,barcode,units_per_strip,strips_per_box,purchase_price,retail_unit_price FROM medicines WHERE active=1 ORDER BY name')->fetchAll();
