html,body{min-height:100%;overflow-x:hidden}.inventory-wrap{max-width:1500px;margin:auto}.top-actions{display:flex;gap:8px;align-items:center}.stats{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}.stat{background:#fff;border:1px solid #e2e8f0;border-radius:10px;padding:9px 14px;min-width:130px}.stat small{display:block;color:#64748b;font-size:10px}.stat b{font-size:16px}.table-wrap{overflow:auto;border:1px solid #e2e8f0;border-radius:10px}.entry{width:100%;min-width:1050px;border-collapse:collapse}.entry th{background:#f8fafc;position:sticky;top:0;z-index:2;font-size:10px;text-transform:uppercase;color:#64748b;padding:8px;text-align:left;white-space:nowrap}.entry td{padding:5px;border-top:1px solid #edf0f4;vertical-align:middle}.entry input{width:100%;box-sizing:border-box;padding:8px 7px;border:1px solid #cbd5e1;border-radius:6px;font-size:12px}.entry .medicine{min-width:230px}.entry .qty{width:72px}.entry .price{width:90px}.entry .batch{width:110px}.entry .expiry{width:130px}.entry .total{font-weight:700;white-space:nowrap;text-align:right;padding-right:10px}.picker{position:relative}.results{position:absolute;z-index:20;left:0;right:0;top:100%;background:#fff;border:1px solid #dfe5ef;border-radius:8px;max-height:230px;overflow:auto;box-shadow:0 10px 25px rgba(20,33,61,.15)}.results button{display:block;width:100%;text-align:left;padding:9px;border:0;border-bottom:1px solid #eee;background:#fff;cursor:pointer}.results button:hover{background:#f4f7ff}.results small{color:#64748b}.actions{display:flex;justify-content:space-between;gap:8px;align-items:center;margin-top:10px;flex-wrap:wrap}.left-actions,.right-actions{display:flex;gap:7px;flex-wrap:wrap}.hint{font-size:10px;color:#64748b}.import-box{margin-top:14px;padding:12px;border:1px dashed #b8c4d8;border-radius:10px;background:#fafcff;display:flex;gap:10px;align-items:center;flex-wrap:wrap}.import-box input{font-size:11px}.optional{font-size:9px;color:#94a3b8;font-weight:400;text-transform:none}.modal-note{font-size:10px;color:#64748b;margin-top:4px}@media(max-width:800px){.page-title{align-items:flex-start}.top-actions{flex-wrap:wrap}.stat{flex:1;min-width:110px}}
</style></head><body><header><div class="brand">💊 <?=h(APP_NAME)?></div><nav><a href="index.php">Dashboard</a><a href="pos.php">POS</a><a class="active" href="manage.php">Management</a></nav><div class="user-info">👤 <?=h(current_user()['username']??'')?> · <?=h(ucfirst(current_user()['role']??''))?> · <a href="logout.php">Logout</a></div></header><main class="inventory-wrap"><div class="page-title"><div><div class="eyebrow">STOCK CONTROL</div><h1>📦 Bulk Inventory</h1><p>Enter many medicines quickly. Select a medicine and only enter the stock you received.</p></div><div class="top-actions"><a class="btn" href="inventory.php">Inventory</a><a class="btn" href="purchases.php">Purchases</a></div></div><?php if(isset($_GET['saved'])):?><div class="success">✓ <?=h($_GET['saved'])?> medicine stock lines received successfully.</div><?php endif;?><?php if($error):?><div class="error">✕ <?=h($error)?></div><?php endif;?><div class="stats"><div class="stat"><small>MEDICINES</small><b id="statRows">0</b></div><div class="stat"><small>TOTAL TABLETS</small><b id="statTabs">0</b></div><div class="stat"><small>TOTAL COST</small><b>Rs. <span id="statCost">0.00</span></b></div><div class="stat"><small>ROWS WITH ERRORS</small><b id="statErrors">0</b></div></div><section class="panel"><div class="table-wrap"><table class="entry" id="tbl"><thead><tr><th>#</th><th>Medicine</th><th>Boxes</th><th>Strips</th><th>Loose Tablets</th><th>Purchase Cost/Tab</th><th>Batch <span class="optional">optional</span></th><th>Expiry <span class="optional">optional</span></th><th>Total Tablets</th><th></th></tr></thead><tbody></tbody></table></div><div class="actions"><div class="left-actions"><button type="button" class="btn" id="add">＋ Add Row</button><button type="button" class="btn" id="duplicate">⧉ Duplicate Last</button><button type="button" class="btn" id="clear">✕ Clear Empty</button></div><div class="right-actions"><span class="hint">Batch and expiry are optional. Use Tab to move quickly between fields.</span><button type="button" class="btn" id="save">💾 SAVE INVENTORY</button></div></div><div class="import-box"><b>📊 Excel / CSV</b><span class="hint">For many medicines, import your file into the same table.</span><input id="file" type="file" accept=".csv,.xlsx,.xls"><button type="button" class="btn" id="download">⬇ Download CSV Template</button></div></section></main><script>
const meds=<?=json_encode($meds,JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP)?>;const body=document.querySelector('#tbl tbody');const $=id=>document.getElementById(id);function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));}function addRow(data={}){const tr=document.createElement('tr');tr.innerHTML='<td class="num"></td><td class="medicine"><div class="picker"><input class="search" placeholder="Type medicine name..." autocomplete="off"><input class="id" type="hidden"><div class="results" hidden></div></div></td><td><input class="boxes qty" type="number" min="0" value="0"></td><td><input class="strips qty" type="number" min="0" value="0"></td><td><input class="tabs qty" type="number" min="0" value="0"></td><td><input class="cost price" type="number" step="0.0001" min="0" value="0"></td><td><input class="batch" placeholder="Optional"></td><td><input class="expiry" type="date"></td><td class="total">0</td><td><button type="button" class="btn remove" title="Remove">×</button></td>';body.appendChild(tr);const s=tr.querySelector('.search'),r=tr.querySelector('.results'),id=tr.querySelector('.id'),cost=tr.querySelector('.cost');if(data.name)s.value=data.name;if(data.id)id.value=data.id;if(data.boxes!=null)tr.querySelector('.boxes').value=data.boxes;if(data.strips!=null)tr.querySelector('.strips').value=data.strips;if(data.tabs!=null)tr.querySelector('.tabs').value=data.tabs;if(data.cost!=null)cost.value=data.cost;if(data.batch)tr.querySelector('.batch').value=data.batch;if(data.expiry)tr.querySelector('.expiry').value=data.expiry;function render(){const q=s.value.trim().toLowerCase();if(!q){r.hidden=true;return}const found=meds.filter(m=>(m.name+' '+(m.generic_name||'')+' '+(m.strength||'')+' '+(m.barcode||'')).toLowerCase().includes(q)).slice(0,15);r.innerHTML=found.map(m=>'<button type="button" data-id="'+m.id+'"><b>'+esc(m.name)+'</b> '+esc(m.strength||'')+'<br><small>'+(m.units_per_strip||1)+' tablets/strip · '+(m.strips_per_box||1)+' strips/box · Rs.'+Number(m.purchase_price||0).toFixed(2)+'/tab</small></button>').join('')||'<div style="padding:10px">No medicine found.</div>';r.hidden=false;r.querySelectorAll('button').forEach(b=>b.onclick=()=>{const m=meds.find(x=>x.id==b.dataset.id);id.value=m.id;s.value=m.name+(m.strength?' '+m.strength:'');cost.value=m.purchase_price||0;r.hidden=true;calc();nextQty(tr);});}s.addEventListener('input',()=>{id.value='';render()});s.addEventListener('focus',render);tr.querySelectorAll('input').forEach(i=>i.addEventListener('input',calc));tr.querySelector('.remove').onclick=()=>{tr.remove();calc()};calc();}function nextQty(tr){tr.querySelector('.boxes').focus();tr.querySelector('.boxes').select()}function calc(){let rows=0,tabs=0,cost=0,errors=0;body.querySelectorAll('tr').forEach((tr,i)=>{tr.querySelector('.num').textContent=i+1;const m=meds.find(x=>x.id==tr.querySelector('.id').value);if(!m){tr.querySelector('.total').textContent='0';if(tr.querySelector('.search').value.trim())errors++;return}const b=Math.max(0,+tr.querySelector('.boxes').value||0),s=Math.max(0,+tr.querySelector('.strips').value||0),t=Math.max(0,+tr.querySelector('.tabs').value||0),q=b*Number(m.strips_per_box||1)*Number(m.units_per_strip||1)+s*Number(m.units_per_strip||1)+t;tr.querySelector('.total').textContent=q.toLocaleString();if(q>0){rows++;tabs+=q;cost+=q*(+tr.querySelector('.cost').value||0)}});$('statRows').textContent=rows;$('statTabs').textContent=tabs.toLocaleString();$('statCost').textContent=cost.toFixed(2);$('statErrors').textContent=errors;}function collect(){return [...body.querySelectorAll('tr')].map(tr=>({medicine_id:+tr.querySelector('.id').value,batch:tr.querySelector('.batch').value.trim(),expiry:tr.querySelector('.expiry').value,boxes:+tr.querySelector('.boxes').value||0,strips:+tr.querySelector('.strips').value||0,tabs:+tr.querySelector('.tabs').value||0,cost:+tr.querySelector('.cost').value||0})).filter(x=>x.medicine_id)}$('add').onclick=()=>addRow();$('duplicate').onclick=()=>{const last=body.querySelector('tr:last-child');if(!last)return addRow();addRow({id:last.querySelector('.id').value,name:last.querySelector('.search').value,boxes:last.querySelector('.boxes').value,strips:last.querySelector('.strips').value,tabs:last.querySelector('.tabs').value,cost:last.querySelector('.cost').value,batch:last.querySelector('.batch').value,expiry:last.querySelector('.expiry').value});};$('clear').onclick=()=>{body.querySelectorAll('tr').forEach(tr=>{if(!tr.querySelector('.id').value)tr.remove()});calc()};$('save').onclick=()=>{const items=collect();if(!items.length)return alert('Select at least one medicine and enter stock.');const bad=items.filter(x=>x.boxes+x.strips+x.tabs<=0);if(bad.length)return alert('One or more medicines have zero stock.');const f=document.createElement('form');f.method='post';f.action='inventory_bulk.php';const a=document.createElement('input');a.name='action';a.value='bulk_receive';const b=document.createElement('input');b.name='items';b.value=JSON.stringify(items);f.append(a,b);document.body.appendChild(f);f.submit()};$('download').onclick=()=>{const csv='Medicine,Boxes,Strips,Loose Tablets,Purchase Cost/Tab,Batch,Expiry\nPanadol 500mg,10,2,5,5,P123,2027-12-31\nBrufen 400mg,20,0,3,8,,\n';const blob=new Blob([csv],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='bulk_inventory_template.csv';a.click();URL.revokeObjectURL(a.href)};$('file').addEventListener('change',e=>{const file=e.target.files[0];if(!file)return;if(/\.xlsx?$/i.test(file.name)){alert('Excel files are supported by the system, but this browser entry screen currently reads CSV directly. Save your Excel sheet as CSV, then import it.');return}const reader=new FileReader();reader.onload=()=>{const lines=String(reader.result).split(/\r?\n/).filter(x=>x.trim());if(lines.length<2)return alert('CSV is empty.');const rows=lines.slice(1).map(line=>{const p=line.split(',').map(x=>x.trim().replace(/^"|"$/g,''));const name=p[0]||'';const m=meds.find(x=>(x.name+' '+(x.strength||'')).toLowerCase()===name.toLowerCase())||meds.find(x=>x.name.toLowerCase()===name.toLowerCase());return m?{id:m.id,name:m.name+(m.strength?' '+m.strength:''),boxes:p[1]||0,strips:p[2]||0,tabs:p[3]||0,cost:p[4]||m.purchase_price||0,batch:p[5]||'',expiry:p[6]||''}:null}).filter(Boolean);if(!rows.length)return alert('No matching medicines found.');body.innerHTML='';rows.forEach(addRow);calc();alert(rows.length+' medicines loaded into the table. Review them, then click SAVE INVENTORY.')};reader.readAsText(file)});document.addEventListener('click',e=>{if(!e.target.closest('.picker'))document.querySelectorAll('.results').forEach(x=>x.hidden=true)});document.addEventListener('keydown',e=>{if(e.ctrlKey&&e.key==='Enter'){e.preventDefault();$('save').click()}if(e.key==='F2'){e.preventDefault();const s=body.querySelector('tr:last-child .search');if(s){s.focus();s.select()}}});addRow();addRow();
</script></body></html>